import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadManjushaData(){const e=readFileSync(resolve(__dirname,"../../manjusha-painting-explorer/manjusha-data.js"),"utf-8");return new Function(e+"\nreturn { MANJUSHA_INFO, MATERIALS_AND_METHOD, TRADITIONAL_MOTIFS, MYTH_STORIES, ARTISAN_COMMUNITY, GALLERY_IMAGES, REFERENCES };")()}describe("Manjusha Painting Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadManjushaData()}),describe("MANJUSHA_INFO metadata",()=>{it("contains correct Manjusha metadata and GI tag",()=>{expect(e.MANJUSHA_INFO.id).toBe("manjusha-painting"),expect(e.MANJUSHA_INFO.title).toContain("Manjusha"),expect(e.MANJUSHA_INFO.originRegion).toContain("Bihar"),expect(e.MANJUSHA_INFO.giTagStatus).toContain("GI")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.MANJUSHA_INFO.quickStats)).toBe(!0),expect(e.MANJUSHA_INFO.quickStats.length).toBe(6)})}),describe("MATERIALS_AND_METHOD & TRADITIONAL_MOTIFS",()=>{it("contains process steps and traditional motifs",()=>{expect(Array.isArray(e.MATERIALS_AND_METHOD)).toBe(!0),expect(e.MATERIALS_AND_METHOD.length).toBeGreaterThanOrEqual(5),expect(Array.isArray(e.TRADITIONAL_MOTIFS)).toBe(!0),expect(e.TRADITIONAL_MOTIFS.length).toBeGreaterThanOrEqual(4)})}),describe("MYTH_STORIES",()=>{it("contains Bihula–Bishari mythology stories",()=>{expect(Array.isArray(e.MYTH_STORIES)).toBe(!0),expect(e.MYTH_STORIES.length).toBeGreaterThanOrEqual(3),expect(e.MYTH_STORIES.some(e=>e.title.includes("Bihula"))).toBe(!0)})}),describe("ARTISAN_COMMUNITY",()=>{it("contains artisan community details",()=>{expect(e.ARTISAN_COMMUNITY.title).toBeDefined(),expect(e.ARTISAN_COMMUNITY.description).toContain("Bhagalpur")})}),describe("GALLERY_IMAGES & REFERENCES",()=>{it("has non-empty gallery and references",()=>{expect(Array.isArray(e.GALLERY_IMAGES)).toBe(!0),expect(e.GALLERY_IMAGES.length).toBeGreaterThanOrEqual(2),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});